INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('30295448-c370-46aa-9c15-f8abaf70cc8d', '249fc2f7-dbc1-4951-88a8-93bd7310a15b', 'A 75-year-old male patient A private prescription for Morphine sulfate 10 mg tablets (Schedule 2 CD) is presented at a community pharmacy. The prescription is dated 32 days ago and specifies total quantity as 56 tablets without words and figures. (Case Ref: PHARMACY-LAW-1030). Relevant physiological and medication history have been reviewed.', 'Can the pharmacist legally dispense this prescription?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ec1409a3-e636-43ff-a0b4-a284d312a753', '249fc2f7-dbc1-4951-88a8-93bd7310a15b', 'A', 'No, because Schedule 2 prescriptions are valid for only 28 days from date of signing and require total quantity in words and figures', 1, 'Correct. Schedule 2, 3, and 4 Controlled Drug prescriptions are legally valid for 28 days only. Schedule 2 and 3 prescriptions mandate total quantity in both words and figures.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c2662be7-d82e-4ce4-b8e6-1f8866ddf505', '249fc2f7-dbc1-4951-88a8-93bd7310a15b', 'B', 'Dispense half the quantity and request an amended prescription for the balance', 0, 'Illegal. An invalid CD prescription cannot be partially dispensed.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9e8d89d6-43a0-44db-9614-2adc308440e9', '249fc2f7-dbc1-4951-88a8-93bd7310a15b', 'C', 'Dispense the full supply and annotate the words and figures manually without prescriber amendment', 0, 'Illegal for total quantity. Pharmacists may only amend minor spelling/typographical errors or words/figures if omitted in specific limited home office circular exemptions.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b914c0da-e34a-41bd-a2bf-97b041c8b7ae', '249fc2f7-dbc1-4951-88a8-93bd7310a15b', 'D', 'Accept validity for 6 months as per standard prescription rules', 0, 'Standard POMs are valid for 6 months, but Controlled Drugs (Schedule 2-4) expire at 28 days.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5e8305e8-7cba-45c7-bc19-d2e459d34d48', '249fc2f7-dbc1-4951-88a8-93bd7310a15b', 'E', 'Dispense under emergency supply regulations', 0, 'Schedule 2 and 3 CDs cannot be supplied under emergency supply regulations at patient request (except phenobarbital for epilepsy).', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('2b44b430-4d8a-4091-af6e-8bff6209a4b7', '249fc2f7-dbc1-4951-88a8-93bd7310a15b', 'Schedule 2 and 3 CD prescriptions are valid for 28 days and must contain quantity in both words and figures.', 'Installment prescriptions (FP10MDA) must have the first installment dispensed within 28 days of signing. Reference: Misuse of Drugs Regulations 2001 & MEP 46.', 'Misuse of Drugs Regulations 2001 & MEP 46', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('d15fa926-325f-4588-92ff-b7718ac959fa', '249fc2f7-dbc1-4951-88a8-93bd7310a15b', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('f4d7cd83-8f7d-44ae-a58d-70a89693d769', 'ACP-Q-1031', 1, 'published', 'p-mpharm', 'sub-uti-first', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('4a75f375-bdbf-4dae-aa92-3213816be63e', 'f4d7cd83-8f7d-44ae-a58d-70a89693d769', 'A 22-year-old female patient A 24-year-old male attends community pharmacy with a severe sore throat of 2 days duration. Examination shows purulent tonsillar exudate, severe tonsillar inflammation, temperature 38.6°C, and no cough. FeverPAIN score is calculated as 4. (Case Ref: PHARMACY-FIRST-1031). Relevant physiological and medication history have been reviewed.', 'What is the appropriate action under the Pharmacy First clinical protocol?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6d92c383-77b3-4100-8de4-cf27884053b9', 'f4d7cd83-8f7d-44ae-a58d-70a89693d769', 'A', 'Supply Phenoxymethylpenicillin (Penicillin V) 500 mg QDS for 5 days under PGD with self-care and worsening advice', 1, 'Correct. FeverPAIN score >= 4 indicates high likelihood of streptococcal infection. Penicillin V is first-line under PGD for 5 days.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('764b1c3e-213b-4beb-9b04-9f555e039bf1', 'f4d7cd83-8f7d-44ae-a58d-70a89693d769', 'B', 'Supply Clarithromycin 500 mg BD without checking for penicillin allergy', 0, 'Sub-optimal. Macrolides are reserved strictly for patients with true penicillin allergy due to resistance stewardship.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6cfbee89-e258-4119-b108-93f3e99da855', 'f4d7cd83-8f7d-44ae-a58d-70a89693d769', 'C', 'Supply Dexamethasone 8 mg stat dose for throat swelling without physician review', 0, 'Contraindicated under community pharmacy protocol. High-dose oral corticosteroids are not authorized under this PGD.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('73e3d863-fe59-41fc-af8e-5d434984b1dc', 'f4d7cd83-8f7d-44ae-a58d-70a89693d769', 'D', 'Supply Co-amoxiclav 625 mg TDS', 0, 'Inappropriate broad-spectrum antibiotic. Amoxicillin/co-amoxiclav may cause severe morbilliform rash in undiagnosed glandular fever (EBV).', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('aadb5cad-ddfc-4db8-9a2d-7a33d3e31154', 'f4d7cd83-8f7d-44ae-a58d-70a89693d769', 'E', 'Supply Penicillin V for 14 days', 0, 'NICE NG84 guidelines mandate a 5-day course for acute group A streptococcal pharyngitis.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('790fb2c0-d377-44f7-aed8-f031e528fc18', 'f4d7cd83-8f7d-44ae-a58d-70a89693d769', 'FeverPAIN score 4-5 warrants targeted antimicrobial treatment (Penicillin V for 5 days). Avoid amoxicillin if glandular fever is suspected.', 'FeverPAIN components: Fever, Purulent tonsils, Attend in <= 3 days, Inflamed tonsils, No cough/coryza. Reference: NHS England Pharmacy First Clinical Pathway & NICE NG84.', 'NHS England Pharmacy First Clinical Pathway & NICE NG84', 1789655696, 1789655696);
