INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('349be102-3ebf-4c36-8b81-b33df4ea6fda', 'a3de3e16-3a31-4206-a5aa-8e5c9f2d8e76', 'A 35-year-old female patient A 24-year-old male attends community pharmacy with a severe sore throat of 2 days duration. Examination shows purulent tonsillar exudate, severe tonsillar inflammation, temperature 38.6°C, and no cough. FeverPAIN score is calculated as 4. (Case Ref: PHARMACY-FIRST-1135). Relevant physiological and medication history have been reviewed.', 'What is the appropriate action under the Pharmacy First clinical protocol?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('abf6bcc7-29a7-403e-802b-1b0047df9e43', 'a3de3e16-3a31-4206-a5aa-8e5c9f2d8e76', 'A', 'Supply Phenoxymethylpenicillin (Penicillin V) 500 mg QDS for 5 days under PGD with self-care and worsening advice', 1, 'Correct. FeverPAIN score >= 4 indicates high likelihood of streptococcal infection. Penicillin V is first-line under PGD for 5 days.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('657aa86c-5ca4-48cd-9784-8b778a8b6494', 'a3de3e16-3a31-4206-a5aa-8e5c9f2d8e76', 'B', 'Supply Clarithromycin 500 mg BD without checking for penicillin allergy', 0, 'Sub-optimal. Macrolides are reserved strictly for patients with true penicillin allergy due to resistance stewardship.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f5596c41-f357-4de5-b205-43a825441a50', 'a3de3e16-3a31-4206-a5aa-8e5c9f2d8e76', 'C', 'Supply Dexamethasone 8 mg stat dose for throat swelling without physician review', 0, 'Contraindicated under community pharmacy protocol. High-dose oral corticosteroids are not authorized under this PGD.', 2, 1789655696);
