INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('6e9e4559-12fb-43fe-abf0-6c1e11936884', '3059f35d-deee-428c-9c53-22d305dd0670', 'A 22-year-old female patient A 45-year-old patient with confirmed H. pylori on stool antigen test has no known drug allergies and has not taken macrolide antibiotics previously. (Case Ref: GASTROINTESTINAL-1136). Relevant physiological and medication history have been reviewed.', 'Which 7-day eradication regimen is recommended first-line by NICE?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('94066dc4-55d6-4a25-9c35-ca4f5f1500c7', '3059f35d-deee-428c-9c53-22d305dd0670', 'A', 'PPI twice daily + Amoxicillin 1 g twice daily + Clarithromycin 500 mg twice daily for 7 days', 1, 'Correct. Standard UK first-line triple eradication consists of a full-dose PPI bd + amoxicillin 1g bd + clarithromycin 500mg bd (or metronidazole 400mg bd) for 7 days.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9d849117-c3b8-4c87-a3ad-059fcd4acf3d', '3059f35d-deee-428c-9c53-22d305dd0670', 'B', 'PPI once daily + Amoxicillin 500 mg TDS for 14 days without second antibiotic', 0, 'Sub-optimal. Dual therapy has poor eradication rates; two synergic antibiotics plus twice-daily acid suppression are essential.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('61449d82-bc61-4990-8564-d16f240392ee', '3059f35d-deee-428c-9c53-22d305dd0670', 'C', 'Prescribe Clarithromycin in a patient taking concurrent Simvastatin 40 mg', 0, 'Dangerous interaction. Strong CYP3A4 inhibition increases statin exposure exponentially, causing rhabdomyolysis.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2cf3ac29-290f-4ead-89f3-615caeb6caa1', '3059f35d-deee-428c-9c53-22d305dd0670', 'D', 'Triple therapy containing Ranitidine instead of PPI', 0, 'Deprecated and unavailable; ranitidine was withdrawn globally due to NDMA impurities.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('639880b2-86dc-402a-97e5-f0cc794f80df', '3059f35d-deee-428c-9c53-22d305dd0670', 'E', 'Retest H. pylori via stool antigen 2 days after completing antibiotics', 0, 'False-negative result. Wait at least 4 weeks post-antibiotics and 2 weeks post-PPI before retesting.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('daeb3973-5ffd-4394-bab2-fe3d9d4784f4', '3059f35d-deee-428c-9c53-22d305dd0670', 'H. pylori eradication requires 7 days of PPI bd + two antibiotics. Retest at least 4 weeks after treatment.', 'If penicillin allergic: PPI bd + Clarithromycin 250mg bd + Metronidazole 400mg bd. Reference: NICE NG184: Gastro-oesophageal reflux disease and dyspepsia.', 'NICE NG184: Gastro-oesophageal reflux disease and dyspepsia', 1789655696, 1789655696);
